import{_ as t,o,c as r,a5 as n}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"846-批量调整视频画幅、添加背景、并在画面中叠加自定义标题与正文文本","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["音频视频批处理"],"标签":["9:16 竖屏视频制作","批量添加视频文本","视频尺寸修改工具","视频背景自定义"]},"headers":[],"relativePath":"md/音频视频批处理/846-批量调整视频画幅、添加背景、并在画面中叠加自定义标题与正文文本.md","filePath":"md/音频视频批处理/846-批量调整视频画幅、添加背景、并在画面中叠加自定义标题与正文文本.md"}'),a={name:"md/音频视频批处理/846-批量调整视频画幅、添加背景、并在画面中叠加自定义标题与正文文本.md"};function s(e,p,g,i,l,h){return o(),r("div",null,[...p[0]||(p[0]=[n('<p>可视化的视频批量处理工具，主打视频尺寸调整、自定义文本添加、背景样式设置等核心功能。无需专业视频编辑技能，即可完成视频分辨率比例适配、文本层自定义（标题 / 内容双文本）、背景（纯色 / 图片）设置，支持批量处理、可视化预览、配置保存 / 导入，适配 mp4、avi、mkv、mov 等主流视频格式，适合自媒体、办公场景下的视频批量标准化处理。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251129110603176438556359749.jpg" alt=""></p><h3 id="功能亮点" tabindex="-1">功能亮点 <a class="header-anchor" href="#功能亮点" aria-label="Permalink to &quot;功能亮点&quot;">​</a></h3><p><strong>拖放/批量导入</strong>：直接把多个视频拖入列表，支持逐条或批量配置。</p><p><strong>多比例画布</strong>：内置 16:9、9:16、4:3、1:1、18:9、21:9、4:5、3:4 等主流比例，可随时切换。</p><p><strong>背景自定义</strong>：支持预设纯色（黑 / 白 / 红 / 蓝 / 绿）、自定义 RGB 颜色、背景图片（PNG/JPG/BMP/GIF），满足不同视觉需求；</p><p><strong>文本精细化编辑</strong>：</p><p>标题 / 内容双文本层独立配置，支持自定义字体（TTF/TTC/OTF）、大小（10-200）、颜色；</p><p>文本可拖拽移动、缩放，右键菜单支持左 / 中 / 右、上 / 中 / 下对齐，行间距调整；</p><p>文本内容双击可直接编辑，实时同步到配置；</p><p><strong>实时/手动预览</strong>：可勾选“实时预览”自动刷新，也可手动点击“更新预览效果”生成一次静态图。</p><p><strong>配置管理</strong>：随时保存/导入 JSON 配置（包含文本位置、颜色、字体、背景等），便于复用模板。</p><p>输出路径默认为 <code>{原文件名}_调整.{扩展名}</code>，存放在源文件同目录。</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p><strong>场景 1：批量制作 9:16 竖屏短视频（抖音 / 快手适配）</strong></p><p><strong>需求</strong>：将 10 个 16:9 横屏 MP4 视频转为 9:16 竖屏，黑色背景，视频居中显示，添加白色标题 “产品开箱”（字体大小 60，微软雅黑），内容文本 “点击查看详情”（字体大小 30，白色），右对齐。</p><p><strong>操作步骤</strong>：</p><p>拖放 10 个视频到列表，选中第一个视频；</p><p>比例选择 “9:16”，对齐方式 “垂直居中对齐”，背景选 “黑色”；</p><p>标题输入 “产品开箱”，大小 60，颜色白色，点击 “选择字体” 也可以不选择，使用默认字体；</p><p>内容输入 “点击查看详情”，大小 30，颜色白色；</p><p>预览区域右键添加标题 / 内容文本，右键文本选择 “右对齐”，调整行间距为 “大”；</p><p>点击 “应用到所有视频”，保存配置为 “竖屏短视频配置.json”；</p><p>点击 “更新预览效果” 确认，点击 “开始处理”；</p><p><strong>预期结果</strong>：所有视频转为 9:16 竖屏，黑色背景，视频居中，右侧显示白色标题和内容，行间距增大，输出文件保存在原目录。</p><p><strong>场景 2：批量添加品牌水印（1:1 方形视频）</strong></p><p><strong>需求</strong>：将 5 个 MOV 视频转为 1:1 方形，背景用品牌 LOGO 图片（透明 PNG），添加红色品牌名 “XX 科技”（字体大小 48，居中对齐），批量处理。</p><p><strong>操作步骤</strong>：</p><p>添加 5 个 MOV 视频到列表，选中第一个；</p><p>比例选择 “1:1”，对齐方式 “垂直底部对齐”；</p><p>点击 “选择图片”，选品牌 LOGO PNG 文件；</p><p>标题输入 “XX 科技”，大小 48，颜色红色，默认宋体；</p><p>预览区域右键添加标题文本，选择 “居中对齐”；</p><p>点击 “应用到所有视频”，点击 “开始处理”；</p><p><strong>预期结果</strong>：视频转为 1:1 方形，背景为 LOGO，视频底部对齐，居中显示红色品牌名，保留原视频音频。</p><h3 id="可视化编辑说明" tabindex="-1">可视化编辑说明 <a class="header-anchor" href="#可视化编辑说明" aria-label="Permalink to &quot;可视化编辑说明&quot;">​</a></h3><p>点击 “更新预览效果”，生成视频第一帧预览背景；</p><p>预览区域右键，选择 “添加标题文本 / 添加内容文本”，生成可交互文本框；</p><p>文本框操作：</p><p>拖拽：按住左键拖动，调整文本位置；</p><p>缩放：拖动文本框右下角手柄，调整字体大小；</p><p>编辑内容：双击文本框，直接修改文字（失去焦点后同步到输入框）；</p><p>右键菜单：支持对齐（左 / 中 / 右、上 / 中 / 下）、颜色设置、行间距（默认 / 大）。</p><h3 id="批量配置" tabindex="-1">批量配置 <a class="header-anchor" href="#批量配置" aria-label="Permalink to &quot;批量配置&quot;">​</a></h3><p><strong>应用到所有视频</strong>：编辑好单个视频配置后，点击该按钮，将当前配置同步到列表所有视频；</p><p><strong>保存配置</strong>：点击 “保存配置”，将所有视频的配置保存为 JSON 文件（含路径、分辨率、文本、背景等），方便后续复用；</p><p><strong>导入配置</strong>：点击 “导入配置”，选择之前保存的 JSON 文件，自动加载视频列表和对应配置（无效路径会自动忽略）。</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251129110646176438560648978.png" alt=""></p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p><strong>文本设置</strong>：</p><p>文本含特殊字符（单引号、冒号）时，工具自动转义，无需手动处理；</p><p>自定义字体路径避免含空格 / 中文特殊字符；</p><p><strong>背景图片</strong>：</p><p>背景图片分辨率建议与目标视频比例一致，避免拉伸变形；</p><p>透明 PNG 背景可正常使用；</p><p><strong>路径要求</strong>：</p><p>视频 / 背景 / 字体文件路径需为纯英文 / 数字，避免中文特殊字符（如 “#、@、空格”）；</p><p><strong>预览限制</strong>：</p><p>预览仅生成视频第一帧效果，若视频开头无画面，以最终处理结果为准；</p><p><strong>异常处理</strong>：</p><p>工具崩溃时，已处理的视频不会丢失，未处理的可重新加载配置处理；</p><p>若文本不显示，检查文本颜色与背景色是否一致、字体大小是否过小。</p><h3 id="常见问题解答-faq" tabindex="-1">常见问题解答（FAQ） <a class="header-anchor" href="#常见问题解答-faq" aria-label="Permalink to &quot;常见问题解答（FAQ）&quot;">​</a></h3><p><strong>Q2：添加文本后预览 / 处理后视频无文本？</strong></p><p>A：1. 检查文本内容是否为空、字体大小是否≥10；<br> 2. 自定义字体加载失败（日志提示 “字体文件无有效字体族”），更换宋体 / 微软雅黑重试；<br> 3. 文本颜色与背景色一致（如白色文本 + 白色背景），修改文本颜色；</p><p><strong>Q3：处理后的视频画面变形？</strong></p><p>A：1. 确认比例选择正确（如横屏视频选 9:16 会拉伸，建议先裁剪）；<br> 2. 背景图片分辨率与目标视频比例不一致，更换匹配比例的图片；</p><p><strong>Q4：预览区域右键无法添加文本？</strong></p><p>A：1. 需先选中列表中的视频文件，再点击 “更新预览效果” 生成背景；<br> 2. 重启工具，排除界面卡顿；<br> 3. 检查视频文件是否损坏（用播放器打开验证）。</p><p><strong>Q5：批量处理部分视频失败？</strong></p><p>A：1. 失败视频路径含特殊字符，修改路径为纯英文；<br> 2. 视频被其他程序占用（如播放器未关闭），关闭后重试；<br> 3. 视频编码不被 FFmpeg 支持，转换为 MP4 后再处理。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>使用前准备</strong></p><p><strong>1. 配置（核心）</strong></p><p><strong>先将apitool文件夹复制到C盘根目录下，如下图所示：</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251010144245176007856553033-5.jpg" alt=""></p><p><strong>2. 字体准备</strong></p><p>请确认<code>C:\\Windows\\Fonts\\simsun.ttc</code>存在（该字体为系统默认宋体，一般都有，如果没有则复制该文件到<code>C:\\Windows\\Fonts\\文件夹下</code>）；</p><p>自定义字体需提前准备 TTF/TTC/OTF 格式文件，避免使用特殊编码字体。</p><p><strong>将如下快捷方式放到桌面双击即可使用</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251129111815176438629564267.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2187.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2187.html</a></p>',89)])])}const d=t(a,[["render",s]]);export{c as __pageData,d as default};
